-- ---------------------------------------------------------------------------
-- 2) Strip the 4 invisibility auras from the 6 templates
-- ---------------------------------------------------------------------------
-- Same surgery 273_ performed on `creature_addon`, applied here to
-- `creature_template_addon`. REGEXP_REPLACE with word boundaries so 64573 can
-- never match inside another id, then a second pass collapses the double space
-- a removal leaves behind, then TRIM. Written as one statement per template so
-- the before/after of each is visible and each is independently revertible.
--
-- 3634123 keeps 52855; the other five had nothing else, so they end up with an
-- empty aura string, which is exactly what the row looked like before 273_'s
-- family of imports started populating this column.
UPDATE acore_world.`creature_template_addon`
   SET `auras` = '52855'
 WHERE `entry` = 3634123 AND `auras` = '64573 52855';

UPDATE acore_world.`creature_template_addon`
   SET `auras` = ''
 WHERE `entry` IN (3634160, 3634163) AND `auras` = '64573';

UPDATE acore_world.`creature_template_addon`
   SET `auras` = ''
 WHERE `entry` = 3634283 AND `auras` = '65097';

UPDATE acore_world.`creature_template_addon`
   SET `auras` = ''
 WHERE `entry` = 3634424 AND `auras` = '65499';

UPDATE acore_world.`creature_template_addon`
   SET `auras` = ''
 WHERE `entry` = 3636210 AND `auras` = '78718';

